    prefix = version
    parts = tuple(parts) + (0,) * (3 - len(parts))
    return {
        "=": prefix == parts,
        ">": prefix > parts,
        ">=": prefix >= parts,
        "<": prefix < parts,
        "<=": prefix <= parts,
    }[op]


