        ({"x": [], "y": {}, "z": [[1]]}, [("x", []), ("y", {}), ("z[0][0]", 1)]),
        ({}, []),
        ({"a": 1}, [("a", 1)]),
        ({"a": {"b": {"c": {"d": 2}}}}, [("a.b.c.d", 2)]),
        ({"l": [1, [2, [3]]]}, [("l[0]", 1), ("l[1][0]", 2), ("l[1][1][0]", 3)]),
        ({"a": [{}]}, [("a[0]", {})]),
        ({"k": (1, 2)}, [("k", (1, 2))]),
        ({"s": "str", "f": 1.5, "t": True}, [("s", "str"), ("f", 1.5), ("t", True)]),
