        ("080442957x", "9780804429573"),
        ("9780804429573", "080442957X"),
        ("0-8044-2957-X", "9780804429573"),
        ("000000000-0", "9780000000002"),
        ("9780000000002", "0000000000"),
    ],
)
def test_convert(isbn, expected):
