def _check_properties(p, bp, m, rows):
    r = Fraction(bp, 120000)
    assert len(rows) == m
    assert sum(row[2] for row in rows) == p  # the loan is fully repaid
    regular = _half_up(Fraction(p, m) if r == 0 else p * r / (1 - (1 + r) ** -m))
    balance = p
