        fields = ["".join(rng.choice('ab ,;"|\tx') for _ in range(rng.randint(0, 5))) for _ in range(rng.randint(1, 6))]
        line = _encode(fields, delim, rng)
        assert list(parse_csv_line(line, delim)) == fields, (line, delim)

