    "doc, pointer, expected",
    [
        ({"a": {"b/c": [10, 20]}}, "/a/b~1c/1", 20),
        ({"": 1}, "/", 1),
        (DOC, "", DOC),
        (DOC, "/n", 4),
        (DOC, "/a/m~0n", 8),
        (DOC, "/~01", 5),
        (DOC, "/~1", 6),
        (DOC, "/0", "zero"),
        (DOC, "/ ", 7),
        (DOC, "/a//", 3),
        (DOC, "/list/1/0", 2),
        (DOC, "/list/2/k", None),
        (DOC, "/list/2", {"k": None}),
        ([[], [[7]]], "/1/0/0", 7),
        (5, "", 5),
    ],
)
def test_lookup(doc, pointer, expected):
    assert json_pointer_get(doc, pointer) == expected


